4e0d\u4e00\u81f4\u5373\u4e2d\u6b62\u5f53\u6b21\u8bc4\u6d4b\uff09\u3002\n\n| # | \u9501\u5b9a\u91cf | \u56fa\u5b9a\u65b9\u6cd5 | \u56fa\u5b9a\u65f6\u70b9 / \u8d23\u4efb\u4eba |\n|---|---|---|---|\n| C1 | \u89c4\u6a21\u6863\u4f4d\u4e0e tokenizer | \u4e24\u7ec4\u5747 7B\u3001\u540c tokenizer \u5bb6\u65cf\uff1b\u52a0\u8f7d\u540e\u65ad\u8a00 tokenizer \u7c7b\u578b\u3001\u8bcd\u8868\u5927\u5c0f\u3001\u7279\u6b8a token \u96c6\u5408\u4e00\u81f4 | \u6a21\u578b\u9009\u53d6\u6b65\uff08\u7814\u7a76\u5458\u786e\u8ba4 checkpoint ID\uff09+ \u52a0\u8f7d\u811a\u672c assert |\n| C2 | \u8bc4\u6d4b\u6846\u67b6\u7248\u672c | lm-evaluation-harness \u56fa\u5b9a\u5230\u5355\u4e00 git commit hash\uff08[\u5047\u8bbe]\u6846\u67b6\u9009\u62e9\uff0c\u5f85\u786e\u8ba4\uff09 | env_setup.sh \u4e2d `pip install git+\u2026@<commit>`\uff0c\u5199\u5165 manifest |\n| C3 | \u4efb\u52a1\u6ce8\u518c\u9879\u4e0e\u63d0\u793a\u6a21\u677f | \u4ec5\u7528 C2 \u9501\u5b9a\u7248\u672c\u4e2d\u7684\u9ed8\u8ba4\u4efb\u52a1\u6ce8\u518c\u9879\uff1b\u7981\u6b62\u81ea\u5b9a\u4e49\u6a21\u677f | \u968f C2 \u81ea\u52a8\u9501\u5b9a\uff1bconfigs \u4e2d\u4e0d\u5f97\u51fa\u73b0 template \u8986\u76d6\u5b57\u6bb5 |\n| C4 | few-shot \u6570\u91cf | `num_fewshot: 0` \u5199\u5165\u4e24\u4efd YAML\uff0cconfig \u5feb\u7167\u5165\u6863 | configs \u5b9a\u7a3f\u6b65 |\n| C5 | \u6253\u5206\u65b9\u5f0f | \u591a\u9009\u578b\u4efb\u52a1\u4e00\u5f8b\u5f52\u4e00\u5316 loglikelihood \u5224\u522b\uff08`fewshot_as_multichoice` \u4e0e `do_sample: false` \u7c7b\u53c2\u6570\u663e\u5f0f\u58f0\u660e\uff09\uff1b\u82e5\u6700\u7ec8\u53e3\u5f84\u542b\u751f\u6210\u5f0f\u4efb\u52a1\uff0c\u5355\u5217\u5e76\u53e6\u5b9a\u6253\u5206\u6cd5 | configs \u5b9a\u7a3f\u6b65 |\n| C6 | \u6570\u503c\u7cbe\u5ea6 | \u7edf\u4e00 bf16\uff08\u6216 fp16\uff0c\u4e8c\u9009\u4e00\u5199\u5165 manifest\uff09 | configs \u5b9a\u7a3f\u6b65 |\n| C7 | \u6700\u5927\u957f\u5ea6\u4e0e\u622a\u65ad | \u7edf\u4e00 `max_seq_len`\uff08\u5efa\u8bae 2048\uff0c\u6765\u6e90\u4f9d\u636e\uff1a\u5f85\